let notificationsEnabled = false

export function getNotificationsEnabled(): boolean {
  return notificationsEnabled
}

export function setNotificationsEnabled(value: boolean): void {
  notificationsEnabled = value
}

import { toggleNotifications } from "./actions"
import { getNotificationsEnabled } from "./preferences"

export default async function Home() {
  const enabled = getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? "on" : "off"}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? "off" : "on"}
        </button>
      </form>
    </main>
  )
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
